N="تعليمات مكتبة جامعة العلوم والتكنولوجيا الأردنية"
F=[]
def r(c,a,q1,q2,q3): F.append(("rule",[1],c,a,q1,q2,q3))
r("المادة 2","في تعليمات المكتبة: المكتبة هي مكتبة الجامعة، والمدير هو مدير المكتبة، واللجنة هي لجنة المكتبة، واللجنة الفرعية هي لجنة المكتبة المشكلة في كل كلية أو عمادة، والمواد المكتبية هي الكتب والدوريات والمواد السمعية والبصرية والمصادر الإلكترونية.","ما المقصود بالمواد المكتبية في تعليمات المكتبة؟","ما المقصود باللجنة الفرعية في تعليمات المكتبة؟","شو بتشمل المواد المكتبية؟")
r("المادة 3","يشكل رئيس الجامعة في مطلع كل عام جامعي لجنة المكتبة برئاسة أحد نواب الرئيس وعضوية مدير المكتبة (مقرراً) ونائب العميد في كل كلية أو عمادة.","من يرأس لجنة المكتبة وما أعضاؤها؟","متى يشكل رئيس الجامعة لجنة المكتبة؟","مين بيكون بلجنة المكتبة؟")
r("المادة 3","تتولى لجنة المكتبة رسم السياسة العامة للمكتبة واقتراح خطط تطويرها والتوصية بتعديل تعليماتها واقتراح وسائل تحسين خدماتها، وتقديم التوصيات بمخصصات المكتبة في موازنة الجامعة، والنظر في توفير مصادر المعلومات وخدمات المكتبة.","ما مهام لجنة المكتبة؟","من يرسم السياسة العامة للمكتبة؟","شو بتعمل لجنة المكتبة؟")
r("المادة 3 (د، هـ)","تنسق لجنة المكتبة بين الكليات والمكتبة في شراء المواد المكتبية والاشتراك في الدوريات وقواعد البيانات واقتراح استراتيجيات الحوسبة، وتناقش القضايا التي لم يرد عليها نص وتوصي بها إلى الرئيس.","من ينسق بين الكليات والمكتبة في شراء المواد المكتبية؟","لمن توصي لجنة المكتبة في القضايا التي لا نص فيها؟","مين بنسق شراء الكتب بين الكليات والمكتبة؟")
r("المادة 4","تشكل في كل كلية بقرار من العميد لجنة فرعية خاصة بالمكتبة، ممثل الكلية في اللجنة مقرر لها وعضوية ممثل عن كل قسم أكاديمي، وتنسق بين الكلية والمكتبة في شراء المواد المكتبية.","كيف تشكل لجنة المكتبة الفرعية في الكلية؟","ما مهمة لجنة المكتبة الفرعية في الكلية؟","مين بشكل لجنة المكتبة بالكلية؟")
r("المادة 5 (أ)","تشتري المكتبة نسخة واحدة من كل مادة مكتبية بناء على اقتراحات أعضاء الهيئة التدريسية، ويجوز شراء أكثر من نسخة بموافقة العميد وبحد أعلى خمس نسخ.","كم نسخة تشتري المكتبة من كل مادة مكتبية؟","ما الحد الأعلى لعدد نسخ الكتاب الذي يمكن شراؤه بموافقة العميد؟","كم نسخة بتشتري المكتبة من الكتاب؟")
r("المادة 5 (ب، ج)","للمدير المبادرة بشراء نسخة واحدة من المواد المكتبية التي يراها مناسبة، وله شراء عشر نسخ كحد أعلى من الكتب التي يؤلفها العاملون في الجامعة وخمس نسخ من كتب المؤلفين الأردنيين، وإذا زاد العدد تشترط موافقة الرئيس.","كم نسخة يشتري مدير المكتبة من الكتب التي يؤلفها العاملون في الجامعة؟","متى تشترط موافقة الرئيس على شراء نسخ إضافية من كتاب مؤلف؟","كم نسخة بشتري المدير من كتب المؤلفين الأردنيين؟")
r("المادة 6","يتم الاشتراك بالدوريات وقواعد البيانات الإلكترونية بالطلب المباشر من الكلية أو الوحدة أو المركز بالتنسيق مع المدير وبموافقة الرئيس.","كيف يتم الاشتراك بالدوريات وقواعد البيانات الإلكترونية؟","من يوافق على الاشتراك بالدوريات وقواعد البيانات؟","مين بوافق على الاشتراك بقواعد البيانات؟")
r("المادة 7 (أ، د)","تعير المكتبة عضو هيئة التدريس 15 كتاباً من كتب المجموعات العامة كحد أعلى ولمدة 4 أشهر، وتعير الموظف في الجامعة 3 كتب كحد أعلى لمدة 3 أسابيع.","كم كتاباً تعير المكتبة عضو هيئة التدريس ولأي مدة؟","كم كتاباً يستعير موظف الجامعة ولأي مدة؟","كم كتاب بقدر أستعير كموظف؟")
r("المادة 7 (هـ)","يجوز معاملة أعضاء الهيئة التدريسية الذين انتهت خدماتهم بسبب بلوغهم السن القانونية، ومن أمضى في خدمة الجامعة خمسة عشر عاماً واستقال، معاملة أعضاء الهيئة التدريسية العاملين من حيث الاستفادة من خدمات المكتبة وامتيازاتها.","هل يستفيد المتقاعد من أعضاء هيئة التدريس من خدمات المكتبة؟","كم سنة خدمة تلزم للاستقالة والاستفادة من امتيازات المكتبة؟","دكتور استقال بعد 15 سنة، بستفيد من المكتبة؟")
r("المادة 7 (و)","يمكن للمستعير حجز أي كتاب من المجموعات العامة إذا كان معاراً لشخص آخر، ما لم يكن مستدعى من مستعير آخر، وذلك بإحضار الهوية الجامعية إلى مكتب الإعارة.","كيف يحجز المستعير كتاباً معاراً لشخص آخر؟","ماذا يحضر المستعير لحجز كتاب معار؟","كتاب معار لحدا، كيف بحجزه؟")
r("المادة 7 (ز)","يمكن للمستعير تجديد إعارة أي كتاب من المجموعات العامة مرتين فقط إذا لم يكن مستدعى أو محجوزاً لمستعير آخر، ويتم ذلك بإحضار الهوية الجامعية إلى مكتب الإعارة.","كم مرة يمكن تجديد إعارة الكتاب؟","متى لا يمكن تجديد إعارة كتاب؟","كم مرة بقدر أجدد الكتاب؟")
r("المادة 7 (ح)","للمدير الحق في الامتناع عن إعارة أي مادة مكتبية إذا اقتضت المصلحة العامة ذلك.","هل يحق لمدير المكتبة الامتناع عن إعارة مادة مكتبية؟","متى يمتنع مدير المكتبة عن إعارة المواد؟","المدير بقدر يمنع إعارة كتاب؟")
r("المادة 7 (ط)","للمدير الحق في استدعاء أي كتاب معار قبل انتهاء مدة إعارته إذا رأى ضرورة لذلك، وعلى المستعير إعادة الكتاب خلال مدة أقصاها 3 أسابيع من تاريخ إشعار الاستدعاء، وخلاف ذلك تترتب عليه غرامة التأخير في المادة 9 (ج).","خلال كم أسبوع يعيد المستعير الكتاب المستدعى؟","ماذا يترتب إذا لم يعد المستعير الكتاب المستدعى في موعده؟","استدعوا كتاب معي، كم عندي وقت أرجعه؟")
r("المادة 7 (ي)","يمكن استدعاء الكتاب المعار قبل انتهاء مدته إذا طلبه مستعير آخر بشرط موافقة المدير، وعلى المستعير الأول إعادته خلال 3 أسابيع من تاريخ إشعار الاستدعاء.","هل يمكن سحب كتاب معار إذا طلبه مستعير آخر؟","شرط استدعاء الكتاب المعار بطلب من مستعير آخر؟","ممكن يسحبوا كتاب معي إذا حدا ثاني طلبه؟")
r("المادة 7 (م)","تنظم خدمة الإعارة المتبادلة وخدمة تسليم الوثائق بين المكتبة ومكتبات الجامعات الأردنية الرسمية الأخرى والمؤسسات الرسمية بموجب اتفاقيات خاصة.","كيف تنظم خدمة الإعارة المتبادلة بين المكتبات؟","هل توجد خدمة تسليم وثائق بين مكتبة الجامعة والجامعات الأخرى؟","في إعارة متبادلة مع الجامعات الثانية؟")
r("المادة 8 (أ، و)","يوضع الكتاب على رف الحجز بطلب من أعضاء الهيئة التدريسية أو بمبادرة من المدير، وتعار كتب المجموعات الخاصة (باستثناء ما ورد في المادة 7 (ل)) إعارة ليلية وتنطبق عليها تعليمات رف الحجز.","من يطلب وضع الكتاب على رف الحجز؟","كيف تعار كتب المجموعات الخاصة؟","مين بحط الكتاب على رف الحجز؟")
r("المادة 8 (ب)","لا يحق للمستعير أن يستعير أكثر من مادة واحدة من رف الحجز خلال الدوام الرسمي.","كم مادة يستعير الطالب من رف الحجز خلال الدوام الرسمي؟","هل يمكن استعارة أكثر من مادة من رف الحجز في الدوام؟","كم كتاب بقدر آخذ من رف الحجز بالدوام؟")
r("المادة 8 (هـ)","لا يجوز إعارة كتب أخرى من رف الحجز للمستعير إذا ترتب عليه غرامات تزيد على دينارين.","متى يمنع المستعير من استعارة كتب رف الحجز؟","هل تمنع الغرامات التي تزيد على دينارين الاستعارة من رف الحجز؟","عليّ غرامات أكثر من دينارين، بقدر أستعير من رف الحجز؟")
r("المادة 9 (هـ، و)","إذا فقد المستعير جزءاً من مادة متعددة الأجزاء ولم يوفر نسخة بديلة يغرم إما ثمن جميع أجزاء المادة أو غرامة التأخير أيهما أعلى، ويغرم المتسبب في الإتلاف أو التمزيق أو التشويه المتعمد مثلي ثمن المادة ويحال إلى الجهات المعنية في الجامعة للإجراءات التأديبية.","ماذا يغرم من فقد جزءاً من مادة متعددة الأجزاء؟","كم تبلغ غرامة الإتلاف أو التمزيق المتعمد لمادة مكتبية؟","شو عقوبة تمزيق كتاب بالمكتبة؟")
r("المادة 9 (ز، ح)","للمدير الإعفاء الجزئي من غرامات التأخير بحد أعلى 50% من الغرامة بناء على مبررات خطية يقدمها المستعير ويقبلها المدير، وللرئيس الإعفاء الكلي بناء على مبررات خطية يقبلها.","ما الحد الأعلى للإعفاء الجزئي من غرامات التأخير؟","من يملك صلاحية الإعفاء الكلي من غرامات التأخير؟","مين بقدر يعفيني من غرامة الكتاب؟")
r("المادة 10 (ب)","إذا امتنع عضو هيئة التدريس أو موظف الجامعة عن إعادة أي مادة مكتبية مستعارة يبلغ العميد أو المدير المختص لاتخاذ الإجراءات اللازمة بحقه.","ماذا يحدث إذا امتنع عضو هيئة تدريس أو موظف عن إعادة مادة مكتبية؟","لمن يبلغ في حال امتناع الموظف عن إعادة الكتاب؟","إذا موظف ما رجع كتاب، شو بصير؟")
r("المادة 11","ترسل إشعارات التذكير للمستعيرين من أعضاء الهيئة التدريسية والإداريين بالطرق المتاحة، وعدم استلامها لا يعفي المستعير من إرجاع الكتاب في الوقت المحدد المختوم على قسيمة تاريخ الإرجاع في آخر الكتاب.","هل يعفي عدم استلام إشعار التذكير المستعير من إرجاع الكتاب؟","أين يختم موعد إرجاع الكتاب؟","ما وصلني تذكير، بحاسبوني على التأخير؟")
r("المادة 12","يسمح بالاطلاع على المواد المكتبية المحظورة لأغراض البحث العلمي فقط وبموافقة المدير، داخل القاعة المخصصة لها، ولا يسمح باستعارتها أو تصوير أي جزء منها.","هل يسمح بالاطلاع على المواد المكتبية المحظورة؟","هل يمكن تصوير أو استعارة المواد المحظورة؟","كيف بقدر أطلع على كتاب محظور؟")
r("المادة 13 (ب، ج)","يسمح لأعضاء الهيئة التدريسية بالطباعة والتصوير المجاني لمقالات علمية أو فصول من كتب ذات علاقة بالمساقات لوضعها على رف الحجز، ويسمح لعضو الهيئة التدريسية لأغراض البحث بتصوير 200 صفحة في العام الدراسي على أن يقتصر على المواد التي لا يسمح بإعارتها.","كم صفحة يصور عضو هيئة التدريس لأغراض البحث في العام الدراسي؟","هل يصور أعضاء هيئة التدريس مجاناً لرف الحجز؟","كم صفحة بقدر الدكتور يصور بالسنة؟")
r("المادة 13 (د، هـ)","يتم تصوير المقالة الواحدة كاملة لجهات داخل الأردن بـ 50 فلساً للصفحة الواحدة، ولجهات خارج الأردن بـ 10 دولارات للمقالة الواحدة بشيك باسم الجامعة مسحوب على بنك أردني، وتقدم المكتبة مجاناً لأعضاء الهيئة التدريسية خدمة تأمين المقالات العلمية غير المتوافرة فيها والمتوافرة في مكتبات الجامعات الأردنية الرسمية.","كم تكلفة تصوير مقالة كاملة لجهات داخل الأردن وخارجه؟","هل تؤمن المكتبة مقالات غير متوافرة لأعضاء هيئة التدريس مجاناً؟","قديش تصوير المقالة الواحدة؟")
r("المادة 15","للمدير وقف تقديم امتيازات الخدمات المكتبية لفترة زمنية مناسبة أو تبليغ الجهات المختصة في الجامعة عن الأشخاص الذين يسيئون السلوك داخل المكتبة أو يخالفون بشكل متكرر تعليماتها لاتخاذ إجراءات أشد بحقهم.","ماذا يفعل مدير المكتبة مع من يسيء السلوك داخل المكتبة؟","هل يمكن وقف امتيازات المكتبة عن المخالف؟","إذا خالفت تعليمات المكتبة بشكل متكرر، شو بصير؟")
r("المادة 16 (ج)","لا يحق لأي شخص أن يلصق أو يثبت أي بيان أو إعلان أو نشرة في أي مكان بالمكتبة إلا بإذن مسبق من المدير وبالتنسيق مع الجهات المعنية في الجامعة.","هل يجوز لصق إعلان في المكتبة دون إذن؟","من يأذن بتثبيت إعلان أو نشرة في المكتبة؟","بقدر ألصق إعلان بالمكتبة؟")
r("المادة 17 - 19","للرئيس والمدير البت في الحالات التي لم يرد فيها نص في تعليمات المكتبة، وهما مسؤولان عن تنفيذ أحكامها، وتلغي هذه التعليمات جميع الأحكام المتعارضة معها في أي تعليمات أو قرارات سابقة.","من يبت في الحالات التي لا نص فيها في تعليمات المكتبة؟","من المسؤول عن تنفيذ تعليمات المكتبة؟","مين بحل الأمور الي مش مذكورة بتعليمات المكتبة؟")
